			param = ""

		import configparser

		bar = 'safe!'
		conf48394 = configparser.ConfigParser()
		conf48394.add_section('section48394')
		conf48394.set('section48394', 'keyA-48394', 'a-Value')
		conf48394.set('section48394', 'keyB-48394', param)
